const affected=[...Object.keys(PAYLOAD),WORLD_REL,MARKER];
const p=r=>path.join(root,r), exists=r=>fs.existsSync(p(r));
const hashFile=r=>crypto.createHash('sha256').update(fs.readFileSync(p(r))).digest('hex');
const die=m=>{console.error('\nERRO V11.2B: '+m+'\n');process.exit(1);};
if(!exists('package.json'))die('Execute na raiz do Kaetram-Open-develop.');
if(exists(MARKER))die('V11.2/V11.2B ja parece instalado. Rode o TESTAR ou rollback antes de reinstalar.');
