if(world.width!==1152||world.height<1090||world.tileSize!==16)die(`world.json inesperado (${world.width}x${world.height}, tile ${world.tileSize}).`);
if(client.width!==world.width||client.height!==world.height||client.tileSize!==16)die('client map.json nao corresponde ao world.json.');
if(!Array.isArray(world.data)||!Array.isArray(world.collisions))die('world.data/collisions invalido.');
if(!Array.isArray(world.areas?.cidadeEstruturada)||world.areas.cidadeEstruturada[0]?.x!==48||world.areas.cidadeEstruturada[0]?.y!==1056)die('Cidade V11.1B nao encontrada na posicao esperada.');
const collisionTile=world.collisions.find(v=>Number.isInteger(v));
if(!Number.isInteger(collisionTile))die('Nenhum tile nativo de colisao encontrado no world.json.');
const x0=180,y0=1056,W=46,H=34,needed=world.width*world.height;
// Missing trailing cells are implicit zeros in Kaetram; pad only to preserve indexing safely.
