if(world.data.length>needed)die('world.data maior que width*height; mapa inesperado.');
for(let y=y0;y<y0+H;y++)for(let x=x0;x<x0+W;x++){const v=world.data[y*world.width+x];if(!(v===0||v===null||(Array.isArray(v)&&v.length===0)))die(`Regiao reservada da cidade ilustrada nao esta vazia em ${x},${y} (valor ${JSON.stringify(v)}). Nada foi alterado.`);}
