try{
  for(const [rel,b64] of Object.entries(PAYLOAD)){const dst=p(rel);fs.mkdirSync(path.dirname(dst),{recursive:true});fs.writeFileSync(dst,Buffer.from(b64,'base64'));}
  // Apply ONLY the illustrated-city collision mask to the user's current world.
  for(let y=y0;y<y0+H;y++)for(let x=x0;x<x0+W;x++)world.data[y*world.width+x]=0;
  for(const [x,y] of CITY_COORDS)world.data[y*world.width+x]=collisionTile;
  fs.writeFileSync(p(WORLD_REL),JSON.stringify(world));
  fs.writeFileSync(p(MARKER),JSON.stringify({version:VERSION,installedAt:new Date().toISOString(),worldMode:'targeted-city-mask',collisionTile,features:['kaykit-1.7','attack-face-target','illustrated-city-empty-zone','dev-panel-expanded','giveitem-inventory','dev-real-max-hp','low-level-loot','supportlist-fix']},null,2));
  fs.writeFileSync(p(STATE),JSON.stringify({version:VERSION,backupRel,affected,existed,installed:INSTALLED,dynamicWorld:{coords:CITY_COORDS.length,collisionTile}},null,2));
  console.log('\n[V11.2B] INSTALACAO CONCLUIDA.');
  console.log('[V11.2B] world.json preservado; somente a regiao X=180..225 / Y=1056..1089 foi preenchida com as 782 colisoes da cidade.');
  console.log('[V11.2B] Execute TESTAR-V11-2B.cmd antes de yarn build.');
}catch(e){console.error(e);console.error('Falha. Use ROLLBACK-V11-2B.cmd.');process.exit(1);}
